let adminOK=false;function adminLogin(){let p=$('panel');p.replaceChildren(el('h1','🔐 관리자'));let pw=field('관리자 비밀번호','password'),msg=el('p','');let b=btn('로그인',()=>{b.disabled=true;rpc('loginAdmin',pw.value).then(t=>{adminToken=t;adminOK=true;pw.value='';return refresh()}).then(()=>{if(page==='admin')admin()}).catch(e=>{msg.textContent=e.message||'로그인 실패';b.disabled=false})});p.append(pw,b,msg)}function admin(){if(!adminOK)return;let p=$('panel');p.replaceChildren(el('h1','관리자 · 기록 관리'));let search=field('가상 사번 / 닉네임 / 팀 검색'),status=document.createElement('select');['전체','완료','게임오버'].forEach(x=>status.add(new Option(x,x)));let out=el('div','');let h=['일시','상태','소속','팀','가상 사번','닉네임','업무유형','점수','정답','진행','목숨','삭제'];function rows(){let q=search.value.trim();return db.results.filter(r=>[r.emp,r.nick,r.team,r.org].join(' ').includes(q)&&(status.value==='전체'||(r.win?'완료':'게임오버')===status.value))}function values(r){return[new Date(r.endedAt||Date.now()).toLocaleString('ko-KR'),r.win?'완료':'게임오버',r.org||ORGS[r.team],r.team,r.emp,r.nick,r.workType||'기존 기록',r.score,r.correct??r.score/10,r.progress??'—',r.lives??'—']}function render(){out.replaceChildren(tableOf(h,rows().map(r=>[...values(r),btn('삭제',()=>{if(confirm('이 기록을 삭제할까요?')){serverAction('deleteResult',r.id).then(()=>{if(page==='admin')admin()}).catch(err)}})])))}search.oninput=status.onchange=render;p.append(search,status,btn('CSV 추출',()=>csv('관리자기록',h.slice(0,-1),rows().map(values))),btn('전체 기록 초기화',()=>{if(confirm('시즌 2 게임 기록 전체를 삭제할까요?')){serverAction('clearResults').then(()=>{if(page==='admin')admin()}).catch(err)}}),out);render();p.append(el('h2','팀별 대상 인원'));p.append(tableOf(['조직','팀','대상 인원'],NAMES.map(n=>{let i=field('미설정','number');i.min=1;i.value=db.capacity[n]||'';i.onchange=()=>{serverAction('setCapacity',n,Number(i.value)||0).catch(err)};return[ORGS[n],n,i]})));p.append(el('h2','게시판 관리'));db.messages.forEach(m=>p.append(el('p',m.nick+': '+m.text),btn('게시글 삭제',()=>{if(confirm('삭제할까요?')){serverAction('deleteMessage',m.id).then(()=>{if(page==='admin')admin()}).catch(err)}})));p.append(btn('로그아웃',()=>{adminOK=false;home()}))}
let bgmWanted=true;try{bgmWanted=localStorage.getItem('santa_bgm_enabled')!=='off'}catch(e){}let noteIndex=0;function playNote(freq,dur=.2,delay=0,vol=.2,target=bus,type='triangle'){if(!ctx||!target||!freq)return;let o=ctx.createOscillator(),g=ctx.createGain(),t=ctx.currentTime+Math.max(0,delay||0);o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(vol,t+.012);g.gain.exponentialRampToValueAtTime(.0001,t+Math.max(.03,dur));o.connect(g).connect(target);o.start(t);o.stop(t+Math.max(.03,dur)+.02)}function labels(){let txt=bgmWanted?'♫ BGM 끄기':'♫ BGM 켜기';['music','music2','musicMobile'].forEach(id=>$(id).textContent=txt);if(page==='game')$('frame').contentWindow.postMessage({type:'musicState',on:bgmWanted},'*')}function tryStart(){try{if(!ctx){ctx=new(window.AudioContext||window.webkitAudioContext)();bus=ctx.createGain();bus.connect(ctx.destination)}ctx.resume().catch(()=>{});if(!bgmWanted){bus.gain.value=0;return}bus.gain.value=.08;if(loop)return;loop=setInterval(()=>{if(document.hidden||ctx.state!=='running'||!bgmWanted)return;let home=[659,659,659,0,659,659,659,0,659,784,523,587,659,0,0,0,698,698,698,698,698,659,659,659,659,587,587,659,587,784,0,0],game=[523,659,784,659,587,698,880,698,659,784,988,784,698,587,523,0];let melody=page==='game'?game:home;let i=noteIndex++;let f=melody[i%melody.length];if(f){playNote(f,.22,0,.28);playNote(f*2,.13,0,.05,bus,'sine')}if(i%4===0)playNote([262,196,220,196][Math.floor(i/4)%4],.65,0,.12,bus,'sine')},250)}catch(e){}labels()}function toggle(){bgmWanted=!bgmWanted;try{localStorage.setItem('santa_bgm_enabled',bgmWanted?'on':'off')}catch(e){}if(bgmWanted)tryStart();else{if(loop)clearInterval(loop);loop=null;if(bus)bus.gain.value=0}labels()}$('musicMobile').onclick=toggle;$('music').onclick=toggle;$('music2').onclick=toggle;document.addEventListener('pointerdown',e=>{if(!e.target.closest('#music,#music2,#musicMobile'))tryStart()},{capture:true});labels();if(bgmWanted)tryStart();

